        audit.record("REVERSE_CHARGE id=" + invoice.getId() + " number=" + invoice.number()
                + " total=" + invoice.total(taxRate.percent()).toPlainString());
    }
    BigDecimal withheld = invoice.withholding(taxRate.percent());
    if (withheld.signum() > 0) {
